import{_ as a,o as r,c as n,aj as t}from"./chunks/framework.C6uXqnaX.js";const c=JSON.parse('{"title":"Keeping your Angular projects up-to-date","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"update.md","filePath":"update.md"}'),o={name:"update.md"};function l(i,e,s,u,d,p){return r(),n("div",null,e[0]||(e[0]=[t('<h1 id="keeping-your-angular-projects-up-to-date" tabindex="-1">Keeping your Angular projects up-to-date <a class="header-anchor" href="#keeping-your-angular-projects-up-to-date" aria-label="Permalink to &quot;Keeping your Angular projects up-to-date&quot;">​</a></h1><p>Just like Web and the entire web ecosystem, Angular is continuously improving. Angular balances continuous improvement with a strong focus on stability and making updates straightforward. Keeping your Angular application up-to-date enables you to take advantage of leading-edge new features, as well as optimizations and bug fixes.</p><p>This document contains information and resources to help you keep your Angular applications and libraries up-to-date.</p><p>For information about our versioning policy and practices — including support and deprecation practices, as well as the release schedule — see <a href="/reference/releases" title="Angular versioning and releases">Angular versioning and releases</a>.</p><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>If you are currently using AngularJS, see <a href="https://angular.io/guide/upgrade" title="Upgrading from AngularJS" target="_blank" rel="noreferrer">Upgrading from AngularJS</a>. <em>AngularJS</em> is the name for all v1.x versions of Angular.</p></div><h2 id="getting-notified-of-new-releases" tabindex="-1">Getting notified of new releases <a class="header-anchor" href="#getting-notified-of-new-releases" aria-label="Permalink to &quot;Getting notified of new releases&quot;">​</a></h2><p>To be notified when new releases are available, follow <a href="https://x.com/angular" title="@angular on X" target="_blank" rel="noreferrer">@angular</a> on X (formerly Twitter) or subscribe to the <a href="https://blog.angular.dev" title="Angular blog" target="_blank" rel="noreferrer">Angular blog</a>.</p><h2 id="learning-about-new-features" tabindex="-1">Learning about new features <a class="header-anchor" href="#learning-about-new-features" aria-label="Permalink to &quot;Learning about new features&quot;">​</a></h2><p>What&#39;s new? What&#39;s changed? We share the most important things you need to know on the Angular blog in <a href="https://blog.angular.dev/" title="Angular blog - release announcements" target="_blank" rel="noreferrer">release announcements</a>.</p><p>To review a complete list of changes, organized by version, see the <a href="https://github.com/angular/angular/blob/main/CHANGELOG.md" title="Angular change log" target="_blank" rel="noreferrer">Angular change log</a>.</p><h2 id="checking-your-version-of-angular" tabindex="-1">Checking your version of Angular <a class="header-anchor" href="#checking-your-version-of-angular" aria-label="Permalink to &quot;Checking your version of Angular&quot;">​</a></h2><p>To check your application&#39;s version of Angular use the <code>ng version</code> command from within your project directory.</p><h2 id="finding-the-current-version-of-angular" tabindex="-1">Finding the current version of Angular <a class="header-anchor" href="#finding-the-current-version-of-angular" aria-label="Permalink to &quot;Finding the current version of Angular&quot;">​</a></h2><p>The most recent stable released version of Angular appears <a href="https://www.npmjs.com/package/@angular/core" title="Angular on npm" target="_blank" rel="noreferrer">on npm</a> under &quot;Version.&quot; For example, <code>16.2.4</code>.</p><p>You can also find the most current version of Angular by using the CLI command <a href="https://angular.dev/cli/update" target="_blank" rel="noreferrer"><code>ng update</code></a>. By default, <a href="https://angular.dev/cli/update" target="_blank" rel="noreferrer"><code>ng update</code></a> (without additional arguments) lists the updates that are available to you.</p><h2 id="updating-your-environment-and-apps" tabindex="-1">Updating your environment and apps <a class="header-anchor" href="#updating-your-environment-and-apps" aria-label="Permalink to &quot;Updating your environment and apps&quot;">​</a></h2><p>To make updating uncomplicated, we provide complete instructions in the interactive <a href="https://angular.dev/update-guide" target="_blank" rel="noreferrer">Angular Update Guide</a>.</p><p>The Angular Update Guide provides customized update instructions, based on the current and target versions that you specify. It includes basic and advanced update paths, to match the complexity of your applications. It also includes troubleshooting information and any recommended manual changes to help you get the most out of the new release.</p><p>For simple updates, the CLI command <a href="https://angular.dev/cli/update" target="_blank" rel="noreferrer"><code>ng update</code></a> is all you need. Without additional arguments, <a href="https://angular.dev/cli/update" target="_blank" rel="noreferrer"><code>ng update</code></a> lists the updates that are available to you and provides recommended steps to update your application to the most current version.</p><p><a href="/reference/releases#angular-versioning" title="Angular Release Practices, Versioning">Angular Versioning and Releases</a> describes the level of change that you can expect based on a release&#39;s version number. It also describes supported update paths.</p><h2 id="resource-summary" tabindex="-1">Resource summary <a class="header-anchor" href="#resource-summary" aria-label="Permalink to &quot;Resource summary&quot;">​</a></h2><ul><li><p>Release announcements: <a href="https://blog.angular.dev/" title="Angular blog announcements about recent releases" target="_blank" rel="noreferrer">Angular blog - release announcements</a></p></li><li><p>Release details: <a href="https://github.com/angular/angular/blob/main/CHANGELOG.md" title="Angular change log" target="_blank" rel="noreferrer">Angular change log</a></p></li><li><p>Update instructions: <a href="https://angular.dev/update-guide" target="_blank" rel="noreferrer">Angular Update Guide</a></p></li><li><p>Update command reference: <a href="https://angular.dev/cli/update" target="_blank" rel="noreferrer">Angular CLI <code>ng update</code> command reference</a></p></li><li><p>Versioning, release, support, and deprecation practices: <a href="/reference/releases" title="Angular versioning and releases">Angular versioning and releases</a></p></li></ul>',22)]))}const h=a(o,[["render",l]]);export{c as __pageData,h as default};
